func matchBodyForCount(count int) string {
	var builder strings.Builder
	builder.WriteByte('[')
	for index := 0; index < count; index++ {
		if index > 0 {
			builder.WriteByte(',')
		}
		fmt.Fprintf(&builder, `{"component":"libxml2","version":"1.%d"}`, index)
	}
	builder.WriteByte(']')
	return builder.String()
